12	// TestDraftUpdateSaveFailureKeepsDraftAndAllowsRetry 覆盖“内部使用者提交合法的
13	// 草稿修改、患者未停用、目标记录仍是尚未生效的草稿，同一次就诊已有同类生效记录，
14	// 但本地保存失败”的改草稿场景：修改必须明确向调用方报错，不能报告成功，也不能
15	// 把保存问题伪装成参数错误、版本冲突、已生效或权限问题。失败后正式草稿的完整
16	// 内容与提交前一致——记录标识、患者、就诊、类别原样保留，仍是草稿，没有当前
17	// 生效版本，也没有新增历史版本；既有生效记录及其历史不受影响，持有该就诊该
18	// 类别有效整类授权的接收方仍只读到原先的生效内容，看不到旧草稿或此次未保存的
19	// 新内容。改草稿本就不产生审计事件，失败尝试也不能增加或改动审计。
20	//
21	// 保存条件恢复后可以继续修改同一条草稿：成功结果与内部档案、就诊记录视图中的
22	// 完整内容都与提交一致（含换行与首尾空格，按原样保留），记录标识与归属不变，
23	// 不生成生效版本，接收方仍拿不到草稿内容。这条草稿之后生效时，第 1 版必须固化
24	// 最后一次成功保存的内容，而不是之前失败的修改。空白内容被拒绝且原草稿保留；
25	// 已生效记录不能再通过修改草稿覆盖。诊断与医嘱同样适用。
26	func TestDraftUpdateSaveFailureKeepsDraftAndAllowsRetry(t *testing.T) {
27		for _, category := range []string{Diagnosis, Order} {
28			t.Run(category, func(t *testing.T) {
29				testDraftUpdateSaveFailure(t, category)
30			})
31		}
32	}
33	
34	func testDraftUpdateSaveFailure(t *testing.T, category string) {
35		dir := t.TempDir()
36		clk := &fakeClock{t: time.Date(2026, 8, 1, 9, 0, 0, 0, time.UTC)}
37		open := func() *Store {
38			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
39			if err != nil {
40				t.Fatalf("open: %v", err)
41			}
42			return s
43		}
44	
45		s := open()
46		p, err := s.RegisterPatient(doc, "改草稿保存失败患者")
47		if err != nil {
48			t.Fatal(err)
49		}
50		e, err := s.AddEncounter(doc, p.ID, time.Time{})
51		if err != nil {
52			t.Fatal(err)
53		}
54		// 同一次就诊下已有一条同类别的生效记录及其历史。
55		otherContent := "既有生效内容-" + category
56		other, err := s.CreateDraft(doc, p.ID, e.ID, category, otherContent)
57		if err != nil {
58			t.Fatal(err)
59		}
60		otherV1, err := s.ActivateRecord(doc, other.ID)
61		if err != nil {
62			t.Fatal(err)
63		}
64		// 目标记录仍是尚未生效的草稿。
65		draftContent := "目标草稿原内容-第二行也行-" + category
66		target, err := s.CreateDraft(doc, p.ID, e.ID, category, draftContent)
67		if err != nil {
68			t.Fatal(err)
69		}
70		// 接收方持有该就诊该类别当前有效的整类授权。
71		if _, err := s.Grant(doc, p.ID, rcv.ID,
72			[]Scope{{EncounterID: e.ID, Category: category}},
73			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour)); err != nil {
74			t.Fatal(err)
75		}
76	
77		// 提交前的基线：目标草稿、既有记录历史、审计与接收方读取结果。
78		chartBefore, err := s.Chart(doc, p.ID)
79		if err != nil {
80			t.Fatal(err)
81		}
82		targetBefore := findHistory(chartBefore, target.ID)
83		if targetBefore == nil || !targetBefore.HasDraft || targetBefore.DraftContent != draftContent ||
84			targetBefore.CurrentVersion != nil || len(targetBefore.Versions) != 0 {
85			t.Fatalf("unexpected baseline target draft: %+v", targetBefore)
86		}
87		otherHistBefore := findHistory(chartBefore, other.ID)
88		if otherHistBefore == nil || otherHistBefore.CurrentVersion == nil ||
89			otherHistBefore.CurrentVersion.ID != otherV1.ID || len(otherHistBefore.Versions) != 1 {
90			t.Fatalf("unexpected baseline other history: %+v", otherHistBefore)
91		}
92		auditBefore, err := s.AuditEvents(doc, p.ID)
93		if err != nil {
94			t.Fatal(err)
95		}
96		if got := auditActions(auditBefore); got[ActionActivated] != 1 || got[ActionGranted] != 1 {
97			t.Fatalf("unexpected baseline audit: %v", got)
98		}
99		readBefore, err := s.Read(rcv, p.ID, e.ID, category)
100		if err != nil {
101			t.Fatal(err)
102		}
103		if len(readBefore.Records) != 1 || readBefore.Records[0].RecordID != other.ID ||
104			readBefore.Records[0].VersionID != otherV1.ID || readBefore.Records[0].Content != otherContent {
105			t.Fatalf("unexpected baseline read: %+v", readBefore)
106		}
107	
108		// checkIntact 断言：失败尝试之后（以及重开之后），目标记录仍是提交前的那条
109		// 草稿——标识、患者、就诊、类别与完整草稿内容全部原样，仍没有当前生效版本
110		// 与任何历史版本；既有记录历史、审计与接收方可见结果全部维持提交前状态，
111		// 未保存的新内容不出现在任何正式视图里。
112		checkIntact := func(label string, st *Store) {
113			t.Helper()
114	
115			chart, err := st.Chart(doc, p.ID)
116			if err != nil {
117				t.Fatalf("%s: chart: %v", label, err)
118			}
119			hist := findHistory(chart, target.ID)
120			if hist == nil {
121				t.Fatalf("%s: target record missing", label)
122			}
123			if hist.Record.ID != target.ID || hist.Record.PatientID != p.ID ||
124				hist.Record.EncounterID != e.ID || hist.Record.Category != category {
125				t.Fatalf("%s: target record identity changed: %+v", label, hist.Record)
126			}
127			if !hist.HasDraft || hist.DraftContent != draftContent ||
128				!hist.Record.HasDraft || hist.Record.DraftContent != draftContent {
129				t.Fatalf("%s: draft content lost or changed: %+v", label, hist)
130			}
131			if hist.CurrentVersion != nil || hist.Record.CurrentVersionID != "" ||
132				len(hist.Versions) != 0 || len(hist.Record.Versions) != 0 {
133				t.Fatalf("%s: failed update left a version: %+v", label, hist)
134			}
135			// 既有生效记录的历史原样保留。
136			if got := findHistory(chart, other.ID); !reflect.DeepEqual(got, otherHistBefore) {
137				t.Fatalf("%s: other record history changed:\nbefore: %+v\nafter:  %+v", label, otherHistBefore, got)
138			}
139	
140			// 就诊视图中的目标记录同样仍是提交前的草稿。
141			er, err := st.EncounterRecords(doc, p.ID, e.ID)
142			if err != nil {
143				t.Fatalf("%s: encounter records: %v", label, err)
144			}
145			if len(er) != 2 {
146				t.Fatalf("%s: encounter record count changed: %+v", label, er)
147			}
148			for _, rh := range er {
149				if rh.Record.ID == target.ID {
150					if !rh.HasDraft || rh.CurrentVersion != nil || rh.DraftContent != draftContent ||
151						rh.Record.PatientID != p.ID || rh.Record.EncounterID != e.ID ||
152						rh.Record.Category != category {
153						t.Fatalf("%s: target no longer the same plain draft in encounter view: %+v", label, rh)
154					}
155				}
156			}
157	
158			// 改草稿本就不产生审计事件；失败尝试不能增加或改动任何既有事件。
159			audit, err := st.AuditEvents(doc, p.ID)
160			if err != nil {
161				t.Fatalf("%s: audit: %v", label, err)
162			}
163			if !reflect.DeepEqual(audit, auditBefore) {
164				t.Fatalf("%s: audit events changed:\nbefore: %+v\nafter:  %+v", label, auditBefore, audit)
165			}
166	
167			// 接收方仍只读到原先已生效的内容：旧草稿与此次未保存的新内容都不出现，
168			// 目标草稿也没有被计为新增生效记录。
169			res, err := st.Read(rcv, p.ID, e.ID, category)
170			if err != nil {
171				t.Fatalf("%s: receiver read: %v", label, err)
172			}
173			if !reflect.DeepEqual(res, readBefore) {
174				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", label, readBefore, res)
175			}
176			if readRecordIDs(res)[target.ID] {
177				t.Fatalf("%s: failed update leaked the target draft to the receiver", label)
178			}
179		}
180	
181		// 制造本地保存失败：数据文件原位置被同名目录占据，原子改名必然失败，
182		// 与身份、患者状态、记录状态或参数合法性无关。原数据文件先挪到旁边，
183		// 事后原样还原。
184		dataPath := filepath.Join(dir, dataName)
185		backupPath := dataPath + ".saved"
186		if err := os.Rename(dataPath, backupPath); err != nil {
187			t.Fatalf("backup data file: %v", err)
188		}
189		if err := os.Mkdir(dataPath, 0o755); err != nil {
190			t.Fatalf("block data path: %v", err)
191		}
192	
193		// 身份有权、患者未停用、目标记录是草稿，提交内容本身合法（非空白，
194		// 含换行与首尾空格），仅保存失败：明确报错，不能伪装成参数不合法、
195		// 版本冲突、已生效、未找到或权限拒绝等业务结果，也不能报告成功。
196		failedContent := "  未保存的新内容-" + category + "\n第二行 "
197		if _, err := s.UpdateDraft(doc, target.ID, failedContent); err == nil {
198			t.Fatal("draft update must fail when local save fails")
199		} else if errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrConflict) ||
200			errors.Is(err, ErrActive) || errors.Is(err, ErrAccessDenied) ||
201			errors.Is(err, ErrDeactivated) || errors.Is(err, ErrNotFound) {
202			t.Fatalf("save failure surfaced as a business error: %v", err)
203		}
204		// 失败不能留下半截写入的临时文件。
205		if _, statErr := os.Stat(dataPath + ".tmp"); !os.IsNotExist(statErr) {
206			t.Fatalf("failed save left a temp file: %v", statErr)
207		}
208	
209		// 失败后：档案、就诊记录、审计与接收方读取全部维持提交前状态。
210		checkIntact("after failed save", s)
211	
212		// 关闭后从原数据位置重新打开：先恢复保存条件（还原原数据文件），
213		// 失败后的草稿状态在重开后保持一致。
214		if err := s.Close(); err != nil {
215			t.Fatal(err)
216		}
217		if err := os.Remove(dataPath); err != nil {
218			t.Fatalf("unblock data path: %v", err)
219		}
220		if err := os.Rename(backupPath, dataPath); err != nil {
221			t.Fatalf("restore data file: %v", err)
222		}
223		s2 := open()
224		checkIntact("after reopen", s2)
225	
226		// 保存条件恢复后：同一条草稿可以继续修改。提交内容同样带换行与首尾空格，
227		// 必须按原样保留；修改只改变草稿内容，不更换记录标识或归属，不产生版本。
228		retryContent := "  重试提交的新内容-" + category + "\n第二行仍在  "
229		updated, err := s2.UpdateDraft(doc, target.ID, retryContent)
230		if err != nil {
231			t.Fatalf("update draft after save recovered: %v", err)
232		}
233		if updated.ID != target.ID || updated.PatientID != p.ID || updated.EncounterID != e.ID ||
234			updated.Category != category || !updated.HasDraft || updated.DraftContent != retryContent ||
235			updated.CurrentVersionID != "" || len(updated.Versions) != 0 {
236			t.Fatalf("successful update returned an unexpected record: %+v", updated)
237		}
238	
239		// 内部档案视图与返回结果一致：仍是同一条草稿，完整内容即本次提交。
240		chart, err := s2.Chart(doc, p.ID)
241		if err != nil {
242			t.Fatal(err)
243		}
244		hist := findHistory(chart, target.ID)
245		if hist == nil || !hist.HasDraft || hist.DraftContent != retryContent ||
246			!hist.Record.HasDraft || hist.Record.DraftContent != retryContent {
247			t.Fatalf("chart draft content mismatch after retry: %+v", hist)
248		}
249		if hist.Record.ID != target.ID || hist.Record.PatientID != p.ID ||
250			hist.Record.EncounterID != e.ID || hist.Record.Category != category {
251			t.Fatalf("record identity changed after retry: %+v", hist.Record)
252		}
253		if hist.CurrentVersion != nil || hist.Record.CurrentVersionID != "" ||
254			len(hist.Versions) != 0 || len(hist.Record.Versions) != 0 {
255			t.Fatalf("draft update produced a version: %+v", hist)
256		}
257		// 既有记录的历史不受改草稿影响。
258		if got := findHistory(chart, other.ID); !reflect.DeepEqual(got, otherHistBefore) {
259			t.Fatalf("other record history changed by retry:\nbefore: %+v\nafter:  %+v", otherHistBefore, got)
260		}
261	
262		// 就诊记录视图显示相同内容，仍是草稿、同一标识与归属。
263		er, err := s2.EncounterRecords(doc, p.ID, e.ID)
264		if err != nil {
265			t.Fatal(err)
266		}
267		if len(er) != 2 {
268			t.Fatalf("encounter record count changed after retry: %+v", er)
269		}
270		var targetInEncounter *RecordHistory
271		for i := range er {
272			if er[i].Record.ID == target.ID {
273				targetInEncounter = &er[i]
274			}
275		}
276		if targetInEncounter == nil || !targetInEncounter.HasDraft ||
277			targetInEncounter.DraftContent != retryContent || targetInEncounter.CurrentVersion != nil ||
278			targetInEncounter.Record.PatientID != p.ID || targetInEncounter.Record.EncounterID != e.ID ||
279			targetInEncounter.Record.Category != category {
280			t.Fatalf("encounter view of target after retry unexpected: %+v", targetInEncounter)
281		}
282	
283		// 成功的草稿修改同样不产生审计事件：事件集合与提交前完全一致。
284		audit, err := s2.AuditEvents(doc, p.ID)
285		if err != nil {
286			t.Fatal(err)
287		}
288		if !reflect.DeepEqual(audit, auditBefore) {
289			t.Fatalf("audit events changed after successful draft update:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
290		}
291	
292		// 接收方仍只能看到原先的生效记录：草稿内容（无论新旧）都不暴露。
293		res, err := s2.Read(rcv, p.ID, e.ID, category)
294		if err != nil {
295			t.Fatal(err)
296		}
297		if !reflect.DeepEqual(res, readBefore) || readRecordIDs(res)[target.ID] {
298			t.Fatalf("receiver read after successful draft update = %+v, want unchanged effective-only view", res)
299		}
300	
301		// 成功修改后的草稿状态在关闭后重新打开同一数据位置时保持一致。
302		if err := s2.Close(); err != nil {
303			t.Fatal(err)
304		}
305		s3 := open()
306		t.Cleanup(func() { _ = s3.Close() })
307		chart, err = s3.Chart(doc, p.ID)
308		if err != nil {
309			t.Fatal(err)
310		}
311		hist = findHistory(chart, target.ID)
312		if hist == nil || !hist.HasDraft || hist.DraftContent != retryContent ||
313			hist.Record.ID != target.ID || hist.CurrentVersion != nil || len(hist.Versions) != 0 {
314			t.Fatalf("updated draft not preserved after reopen: %+v", hist)
315		}
316	
317		// 边界：空白内容（含纯换行/纯空白）被拒绝并保留当前草稿。
318		if _, err := s3.UpdateDraft(doc, target.ID, "  \n\t "); !errors.Is(err, ErrInvalidArgument) {
319			t.Fatalf("blank content err = %v, want ErrInvalidArgument", err)
320		}
321		chart, err = s3.Chart(doc, p.ID)
322		if err != nil {
323			t.Fatal(err)
324		}
325		if hist = findHistory(chart, target.ID); hist == nil || !hist.HasDraft ||
326			hist.DraftContent != retryContent {
327			t.Fatalf("rejected blank update changed the draft: %+v", hist)
328		}
329	
330		// 草稿之后通过现有操作生效：第 1 版必须固化最后一次成功保存的内容，
331		// 不能采用之前失败的那次修改。
332		activateTime := clk.t.Add(2 * time.Hour)
333		clk.t = activateTime
334		v1, err := s3.ActivateRecord(doc, target.ID)
335		if err != nil {
336			t.Fatalf("activate updated draft: %v", err)
337		}
338		if v1.Number != 1 || v1.RecordID != target.ID || v1.Category != category ||
339			v1.PrevID != "" || v1.Reason != "" {
340			t.Fatalf("bad v1 identity: %+v", v1)
341		}
342		if v1.Content != retryContent {
343			t.Fatalf("v1 content = %q, want last successfully saved content %q", v1.Content, retryContent)
344		}
345		if v1.Content == failedContent {
346			t.Fatalf("v1固化了保存失败那次提交的内容: %q", v1.Content)
347		}
348		if !v1.CreatedAt.Equal(activateTime) {
349			t.Fatalf("v1 time %v != activation time %v", v1.CreatedAt, activateTime)
350		}
351	
352		// 生效后草稿清除，版本链上只有第 1 版。
353		chart, err = s3.Chart(doc, p.ID)
354		if err != nil {
355			t.Fatal(err)
356		}
357		hist = findHistory(chart, target.ID)
358		if hist == nil || hist.CurrentVersion == nil || hist.HasDraft || hist.DraftContent != "" ||
359			!reflect.DeepEqual(*hist.CurrentVersion, v1) || hist.Record.CurrentVersionID != v1.ID ||
360			len(hist.Versions) != 1 || !reflect.DeepEqual(hist.Versions[0], v1) {
361			t.Fatalf("history after activation unexpected: %+v", hist)
362		}
363		// 既有生效记录及其历史不受影响。
364		if got := findHistory(chart, other.ID); !reflect.DeepEqual(got, otherHistBefore) {
365			t.Fatalf("other record history changed after target activation:\nbefore: %+v\nafter:  %+v", otherHistBefore, got)
366		}
367	
368		// 只多出一条生效审计：失败的改草稿尝试始终没有留下事件。
369		audit, err = s3.AuditEvents(doc, p.ID)
370		if err != nil {
371			t.Fatal(err)
372		}
373		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
374			t.Fatalf("audit after activation:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
375		}
376		last := audit[len(audit)-1]
377		if last.Action != ActionActivated || last.ObjectType != "record" || last.ObjectID != target.ID ||
378			last.ActorID != doc.ID || last.PatientID != p.ID {
379			t.Fatalf("unexpected new audit event: %+v", last)
380		}
381	
382		// 生效后整类授权让接收方读到第 1 版（成功保存的内容），看不到任何草稿痕迹；
383		// 既有内容原样保留。
384		res, err = s3.Read(rcv, p.ID, e.ID, category)
385		if err != nil {
386			t.Fatal(err)
387		}
388		if len(res.Records) != 2 {
389			t.Fatalf("receiver read after activation = %+v, want 2 records", res)
390		}
391		byID := map[ID]EffectiveRecord{}
392		for _, rec := range res.Records {
393			byID[rec.RecordID] = rec
394		}
395		if got := byID[target.ID]; got.VersionID != v1.ID || got.Version != 1 ||
396			got.Content != retryContent {
397			t.Fatalf("receiver sees wrong target version: %+v", got)
398		}
399		if got := byID[other.ID]; got.VersionID != otherV1.ID || got.Content != otherContent {
400			t.Fatalf("receiver view of existing record changed: %+v", got)
401		}
402	
403		// 边界：已生效的记录不能再通过修改草稿覆盖；状态与审计均不变。
404		if _, err := s3.UpdateDraft(doc, target.ID, "生效后试图覆盖"); !errors.Is(err, ErrActive) {
405			t.Fatalf("update active record err = %v, want ErrActive", err)
406		}
407		chart, err = s3.Chart(doc, p.ID)
408		if err != nil {
409			t.Fatal(err)
410		}
411		if hist = findHistory(chart, target.ID); hist == nil || hist.HasDraft ||
412			hist.CurrentVersion == nil || hist.CurrentVersion.ID != v1.ID ||
413			hist.CurrentVersion.Content != retryContent || len(hist.Versions) != 1 {
414			t.Fatalf("ErrActive update changed the effective record: %+v", hist)
415		}
416		audit, err = s3.AuditEvents(doc, p.ID)
417		if err != nil {
418			t.Fatal(err)
419		}
420		if got := auditActions(audit); got[ActionActivated] != 2 {
421			t.Fatalf("audit changed after rejected update on active record: %v", got)
422		}
423	}
