	func() {
		withWorkingDir(t, workB)
		seed, err := Open("./data", WithClock(func() time.Time { return clk.t }))
		if err != nil {
			t.Fatalf("seed archive B: %v", err)
		}
		bp, err := seed.RegisterPatient(doc, "新位置档案患者乙")
		if err != nil {
