// 重新解析 B 档案，取出其中的患者标识，用于验证隔离。
ident := func() ID {
	probe, err := Open(filepath.Join(t.TempDir(), "x"))
	_ = probe
	_ = err
	return ""
}()
_ = ident
var bpID ID
{
	probe, err := Open(dirB)
	if err != nil {
		t.Fatalf("probe open B: %v", err)
	}
	// B 里只有一名患者；通过审计之外的简单方式取标识：重新登记会改动 B，
	// 不能这么做，因此直接读句柄内的快照。
	err = probe.view(func(snap *snapshot) error {
		for id := range snap.Patients {
			bpID = id
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if bpID == "" {
		t.Fatal("archive B has no patient")
	}
	if err := probe.Close(); err != nil {
		t.Fatal(err)
	}
}

